import sys, os
from pathlib import Path
import pytest

root = Path('/testbed/qa_instances_eval/cfnlint_qa/template_search_deep_keys_chronological_monotonicity_suite/files').resolve()
os.chdir(root)
if str(root / 'src') not in sys.path:
    sys.path.insert(0, str(root / 'src'))

TARGET_FILE = str((Path('/testbed/src/cfnlint/template/template.py')).resolve())
TARGET_FUNC = '_search_deep_keys'

samples = []


def tracer(frame, event, arg):
    if event == 'line' and frame.f_code.co_name == TARGET_FUNC and Path(frame.f_code.co_filename).resolve() == Path(TARGET_FILE):
        loc = frame.f_locals
        if 'keys' in loc:
            k = loc['keys']
            try:
                lk = len(k)
            except Exception:
                lk = None
        else:
            lk = None
        p = loc.get('path')
        try:
            lp = len(p) if p is not None else None
        except Exception:
            lp = None
        samples.append((lk, lp, frame.f_lineno))
    return tracer

sys.settrace(tracer)
try:
    rc = pytest.main(['tests/qa/testcase.py::TestTemplateSearchDeepKeysChronologicalMonotonicitySuiteQA','-q'])
finally:
    sys.settrace(None)

vals = [k for k,_,_ in samples if isinstance(k, int)]

inc = all(vals[i] > vals[i-1] for i in range(1, len(vals))) if vals else False
nondec = all(vals[i] >= vals[i-1] for i in range(1, len(vals))) if vals else False
dec = all(vals[i] < vals[i-1] for i in range(1, len(vals))) if vals else False
noninc = all(vals[i] <= vals[i-1] for i in range(1, len(vals))) if vals else False

if inc:
    label = 'Strictly Increasing'
elif dec:
    label = 'Strictly Decreasing'
elif nondec:
    label = 'Non-Decreasing'
elif noninc:
    label = 'Non-Increasing'
else:
    label = 'None'

print('rc', rc)
print('events', len(samples), 'vals', len(vals), 'min', min(vals) if vals else None, 'max', max(vals) if vals else None)
print('first30', vals[:30])
print('label', label)
# print one witness of increase/decrease for none
for i in range(1, len(vals)):
    if vals[i] > vals[i-1]:
        print('has_increase_at', i-1, vals[i-1], '->', vals[i])
        break
for i in range(1, len(vals)):
    if vals[i] < vals[i-1]:
        print('has_decrease_at', i-1, vals[i-1], '->', vals[i])
        break
